package com.procurement.compliance_engine.service;
import com.procurement.compliance_engine.classification.SectorTaxonomy;import com.procurement.compliance_engine.dto.TenderResponse;import com.procurement.compliance_engine.repository.TenderClassificationRepository;import com.procurement.compliance_engine.security.CurrentUser;import org.springframework.data.domain.PageRequest;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class BidderRecommendationService {
 private final JdbcTemplate jdbc;private final TenderClassificationRepository classifications;
 public BidderRecommendationService(JdbcTemplate j,TenderClassificationRepository c){jdbc=j;classifications=c;}
 @Transactional(readOnly=true) public Map<String,Object> recommended(String sector,String search,int page,int size){var user=CurrentUser.get();if(user==null||!"BIDDER".equals(user.role()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Bidder account required");if(page<0||size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Page must be non-negative and size must be 1-100");if(sector!=null&&!SectorTaxonomy.contains(sector))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown sector filter");Set<String> codes=new LinkedHashSet<>(jdbc.queryForList("SELECT sector_code FROM bidder_sectors WHERE organization_id=?",String.class,user.organizationId()));if(codes.isEmpty())return Map.of("content",List.of(),"page",page,"size",size,"totalElements",0,"totalPages",0);codes.addAll(jdbc.queryForList("SELECT related_sector_code FROM sector_relationships WHERE sector_code IN (SELECT sector_code FROM bidder_sectors WHERE organization_id=?)",String.class,user.organizationId()));var result=classifications.findRecommendations(codes,sector,search==null||search.isBlank()?null:search.trim(),PageRequest.of(page,size,org.springframework.data.domain.Sort.by("submissionDeadline").ascending()));List<Map<String,Object>> content=result.getContent().stream().map(t->{List<String> matched=classifications.findConfirmedByTender(t.getId()).stream().map(c->c.getSectorCode()).filter(codes::contains).distinct().toList();List<String> capabilities=jdbc.queryForList("SELECT capability FROM bidder_capabilities WHERE organization_id=?",String.class,user.organizationId());List<String> matchedCaps=capabilities.stream().filter(c->(t.getTitle()+" "+t.getDescription()).toLowerCase(Locale.ROOT).contains(c.toLowerCase(Locale.ROOT))).toList();return Map.<String,Object>of("tender",TenderResponse.from(t),"matchingSectors",matched,"matchingCapabilities",matchedCaps,"eligibilityNote","Recommendation is a discovery aid and does not determine tender eligibility.");}).toList();return Map.of("content",content,"page",page,"size",size,"totalElements",result.getTotalElements(),"totalPages",result.getTotalPages());}
}
